def getwordpix(word):
    wordwid = 0
    for char in word:
        if char in arr:
            img = getname(char)
            try:
                wordwid += imgwidth[img]
            except KeyError:
                continue
            except Exception as e:
                print(f"Unexpected error with character '{img}': {e}")
    return wordwid

